import ReactDOM from 'react-dom/client';
import { BrowserRouter, Routes, Route, Navigate } from 'react-router';
import Navbar from './components/Common/Navbar';
import './index.css';
import './icons.css';
import ProductList from './components/Products/ProductList';
import WarehouseList from './components/Warehouses/WarehouseList';
import React from 'react';
import Movements from './components/Movements/Movements';
import Login from './components/Login/Login';

const root = ReactDOM.createRoot(document.getElementById('root'));

function MainPage() {
  const pages = [
    {
      value: '/products',
      name: 'Products'
    },
    {
      value: '/warehouses',
      name: 'Warehouses'
    },
    {
      value: '/movements',
      name: 'Movements'
    }
  ];
  const [title, setTitle] = React.useState('Inventory Management');

  React.useEffect(() => {
    document.title = title;
  }, [title]);

  return (
    <BrowserRouter>
      <Navbar title={title} pages={pages} />
      <Routes>
        <Route index element={<Navigate to="/products" />} />
        <Route path="/products" element={<ProductList setTitle={setTitle} />} />
        <Route path="/warehouses" element={<WarehouseList setTitle={setTitle} />} />
        <Route path="/movements" element={<Movements setTitle={setTitle} />} />
        <Route path="/login" element={<Login setTitle={setTitle} />} />
      </Routes>
    </BrowserRouter>
  );
}

root.render(
    <MainPage />
);